var i=167;var a=[{id:`cooking-167-01`,theoryId:167,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`What most distinguishes a puréed soup from a clear soup?`,ua:`Що найбільше відрізняє суп-пюре від прозорого супу?`},explanation:{en:`Puréed vegetable or legume particles thicken the liquid phase.`,ua:`Подрібнені овочеві або бобові частинки роблять рідину густішою.`},options:[{id:`a`,text:{en:`Blended solids contribute to the soup body`,ua:`Подрібнені тверді компоненти формують густоту`}},{id:`b`,text:{en:`Puréed soups contain no vegetables`,ua:`Супи-пюре не містять овочів`}},{id:`c`,text:{en:`Clear soups are always thickened by flour`,ua:`Прозорі супи завжди загущують борошном`}}],answer:{optionIds:[`a`]}},{id:`cooking-167-02`,theoryId:167,type:`true_false`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Cream soup must always get all its thickness from cream alone.`,ua:`Крем-суп обов’язково має густішати лише завдяки вершкам.`},explanation:{en:`Vegetable purée, starch, roux and other methods can supply body.`,ua:`Пюре з овочів, крохмаль, ру та інші методи також можуть забезпечувати густоту.`},answer:{value:!1}},{id:`cooking-167-03`,theoryId:167,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match soup categories to texture.`,ua:`Поєднайте типи супів із текстурою.`},explanation:{en:`Soup classifications describe structure, not just ingredients.`,ua:`Типи супів описують структуру, а не лише склад.`},leftItems:[{id:`l1`,text:{en:`Clear broth soup`,ua:`Прозорий суп на бульйоні`}},{id:`l2`,text:{en:`Chunky soup`,ua:`Суп зі шматочками`}},{id:`l3`,text:{en:`Puréed soup`,ua:`Суп-пюре`}}],rightItems:[{id:`r3`,text:{en:`Blended particles create thickness`,ua:`Подрібнені частинки створюють густоту`}},{id:`r2`,text:{en:`Distinct solid pieces in liquid`,ua:`Окремі шматочки в рідині`}},{id:`r1`,text:{en:`Mostly free-flowing liquid`,ua:`Переважно рідка основа`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-167-04`,theoryId:167,type:`decision_scenario`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`You need a creamy-feeling vegan soup without dairy. What is a useful technique?`,ua:`Потрібен веганський суп із кремовим відчуттям без молочних продуктів. Який метод підійде?`},explanation:{en:`Fine purée can produce body without dairy; verify any dietary claims.`,ua:`Дрібне пюре дає густоту без молока; склад страви має відповідати дієтичним вимогам.`},options:[{id:`a`,text:{en:`Add hidden butter without telling the guest`,ua:`Додати вершкове масло без попередження гостя`}},{id:`b`,text:{en:`Blend cooked vegetables or legumes into the base`,ua:`Збити варені овочі або бобові з основою`}},{id:`c`,text:{en:`Use raw flour and no further cooking`,ua:`Додати сире борошно без подальшого нагрівання`}}],answer:{optionIds:[`b`]}},{id:`cooking-167-05`,theoryId:167,type:`find_mistake`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Which claim about soup types is wrong?`,ua:`Яке твердження про супи неправильне?`},explanation:{en:`Particle size, viscosity and fat content affect sensory texture.`,ua:`Розмір частинок, в’язкість і жирність впливають на відчуття текстури.`},options:[{id:`a`,text:{en:`Chunky soups retain pieces`,ua:`Супи зі шматочками зберігають цілі компоненти`}},{id:`b`,text:{en:`Puréed soups use blended ingredients`,ua:`Супи-пюре містять подрібнені інгредієнти`}},{id:`c`,text:{en:`All soups have the same mouthfeel regardless of structure`,ua:`Усі супи мають однакове відчуття в роті незалежно від структури`}}],answer:{optionIds:[`c`]}}];var n={theoryId:167,exercises:a};export{n as default,a as exercises,i as theoryId};